targets.expr:
(
  oracledb_compute_stats_value{hostname="$hostname", job="$job", name="sorts (memory)"}
  / 
  on(server, instance, job) 
  (
    sum by (server, instance, job) (oracledb_compute_stats_value{hostname="$hostname", job="$job", name=~"sorts.*"})
  )
) * 100

(
  oracledb_sga_stats_free_bytes{hostname="$hostname", job="$job", pool="shared pool"} 
  / on(server, instance, job) group_left 
  oracledb_db_system_value{hostname="$hostname", job="$job", name="sga_max_size"}
) * 100
